export function rangeWorld(state,inventory){
 const config={enabled:1,rounds:10,round_seconds:5,targets_per_round:3,move_amplitude:10,move_vertical:8,move_speed:100,radius_x:4,radius_y:8,bullseye_percent:42,hit_points:50,bullseye_points:100,fire_interval_ms:500,lag_tolerance_ms:1000,actions_per_minute:180};
 const rules=[{good_id:'homemade-pistol',ammo_good_id:'homemade-bullets',condition_max:100,wear_per_shot:1,enabled:true,version:1}],sessions=[],requests=new Map();let next=1;
 const current=()=>sessions.at(-1),fail=m=>{throw new Error(m);};
 const target=(v,l,e)=>{const c=v.config,r=Math.floor(e/(c.round_seconds*1000)),phase=((v.seed+r*53+l*137)%628)/100,t=e%(c.round_seconds*1000)/1000*c.move_speed/100;return{x:50+(l-(c.targets_per_round-1)/2)*(c.targets_per_round===2?40:30)+c.move_amplitude*Math.sin(t+phase),y:45+c.move_vertical*Math.sin(t*.7+phase)};};
 const read=()=>{const d=inventory.read(),v=current(),now=Date.now();if(v?.status==='active'&&now>Date.parse(v.ends_at)+v.config.lag_tolerance_ms)v.status='finished';const history=sessions.filter(s=>s.status!=='active'),shots=history.reduce((n,v)=>n+v.shots,0),hits=history.reduce((n,v)=>n+v.hits,0);
 return {season:state.season,server_time:new Date().toISOString(),config,can_manage:state.permissions.includes('roles.manage'),weapons:d.gear.filter(g=>g.location==='equipped'&&['primary','secondary'].includes(g.equipment_slot)).map(g=>{const r=rules.find(r=>r.good_id===g.good_id);return{id:g.id,good_id:g.good_id,name:d.goods.find(i=>i.id===g.good_id).name,slot:g.equipment_slot,raw_condition:g.condition,condition:r?Math.min(r.condition_max,g.condition??r.condition_max):null,condition_max:r?.condition_max??null,wear_per_shot:r?.wear_per_shot??null,enabled:r?.enabled??false,ammo_good_id:r?.ammo_good_id??null,ammo_name:d.goods.find(i=>i.id===r?.ammo_good_id)?.name??null};}),ammo:(()=>{const g=d.gear.find(g=>g.location==='equipped'&&g.equipment_slot==='ammo');return g?{id:g.id,good_id:g.good_id,name:d.goods.find(i=>i.id===g.good_id).name,quantity:g.quantity}:null;})(),session:v??null,stats:{sessions:history.length,best_score:Math.max(0,...history.map(s=>s.score)),shots,hits,best_accuracy:Math.max(0,...history.map(s=>s.shots?Math.round(s.hits/s.shots*100):0))},recent:history.slice(-5).reverse(),leaders:history.some(v=>v.shots)?[{player_id:state.player.id,username:state.player.handle,avatar_url:null,score:Math.max(...history.map(v=>v.score))}]:[],management:state.permissions.includes('roles.manage')?{weapons:rules,goods:d.goods,settings:Object.entries(config).map(([key,value])=>({key:'range_'+key,value,minimum:key==='enabled'?0:1,maximum:key==='enabled'?1:10000}))}:null};};
 const action=(kind,p)=>{const prior=requests.get(p.request_id),key=JSON.stringify({kind,p});if(prior)return prior.key===key?{...prior.result,state:read()}:{error:'This reference was already used.'};try{
  if(p.season_id!==state.season.id)fail('The season changed. Refresh the range.');if(kind!=='finish'&&state.season.status!=='open')fail('The season is not open.');const d=read();let message='Session recorded.',result={};
  if(kind==='start'){if(!config.enabled)fail('The shooting range is closed.');if(current()?.status==='active'&&Date.now()<Date.parse(current().ends_at))fail('Finish your current range session first.');if(current()?.status==='active')current().status='finished';const w=d.weapons.find(w=>w.slot===p.equipment_slot);if(!w?.enabled)fail('Equip a weapon in Inventory first.');if(!w.condition)fail('Your weapon is broken.');if(!d.ammo||d.ammo.good_id!==w.ammo_good_id)fail('Equip compatible bullets in Inventory first.');sessions.push({id:'range-'+next++,weapon_id:w.id,weapon_good_id:w.good_id,equipment_slot:w.slot,seed:37,config:structuredClone(config),weapon_rule:structuredClone(rules.find(r=>r.good_id===w.good_id)),started_at:new Date().toISOString(),ends_at:new Date(Date.now()+config.rounds*config.round_seconds*1000).toISOString(),status:'active',shots:0,hits:0,score:0,streak:0,best_streak:0,last_shot_at:null,last_elapsed_ms:-1,hit_targets:[],last_shot:null});message='Range session started. Every shot uses one bullet.';
  }else{const v=sessions.find(s=>s.id===p.session_id);if(!v)fail('This range session is not yours.');if(kind==='finish'){v.status=Date.now()>=Date.parse(v.ends_at)?'finished':'stopped';}else if(kind==='fire'){
   if(!config.enabled||v.status!=='active')fail('This range session is no longer active.');const elapsed=Date.now()-Date.parse(v.started_at),e=p.elapsed_ms,c=v.config;
   if(!Number.isInteger(e)||e<0||e<elapsed-c.lag_tolerance_ms||e>elapsed+100||e<=v.last_elapsed_ms||e>=c.rounds*c.round_seconds*1000)fail('Shot timing expired. Refresh the range clock and try again.');
   if(!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>100||p.y<0||p.y>100)fail('Aim inside the shooting lane.');
   if(v.last_shot_at&&Date.now()-Date.parse(v.last_shot_at)<c.fire_interval_ms)fail('Let your weapon settle before firing again.');
   const w=d.weapons.find(w=>w.id===v.weapon_id&&w.slot===v.equipment_slot);if(!w)fail('Your equipped weapon changed. End this session and start again.');if(!w.condition)fail('Your weapon is broken.');if(!d.ammo||d.ammo.good_id!==v.weapon_rule.ammo_good_id)fail('No compatible bullets equipped.');
   const r=Math.floor(e/(c.round_seconds*1000));let lane=null,best=Infinity;for(let l=0;l<c.targets_per_round;l++){if(v.hit_targets.includes(`${r}:${l}`))continue;const t=target(v,l,e),dist=((p.x-t.x)/c.radius_x)**2+((p.y-t.y)/c.radius_y)**2;if(dist<=1&&dist<best){best=dist;lane=l;}}
   const points=lane===null?0:best<=(c.bullseye_percent/100)**2?c.bullseye_points:c.hit_points;
   inventory.rangeShot(w.id,d.ammo.id,v.weapon_rule.wear_per_shot,v.weapon_rule.condition_max);
   v.shots++;v.hits+=lane===null?0:1;v.score+=points;v.streak=lane===null?0:v.streak+1;v.best_streak=Math.max(v.best_streak,v.streak);v.last_elapsed_ms=e;v.last_shot_at=new Date().toISOString();if(lane!==null)v.hit_targets.push(`${r}:${lane}`);v.last_shot={id:'shot-'+next++,hit:lane!==null,points,round:r,lane,x:p.x,y:p.y,created_at:v.last_shot_at};message=lane===null?'Miss.':points===c.bullseye_points?'Bullseye.':'Target hit.';result={...v.last_shot};
  }else fail('Unknown range action.');}
  result={...result,message};requests.set(p.request_id,{key,result});return {...result,state:read()};
 }catch(e){return{error:e.message};}};
 const manage=(kind,p)=>{if(!state.permissions.includes('roles.manage'))return{error:'Range management permission required.'};if(kind==='settings'){for(const [k,v]of Object.entries(p.settings))config[k.replace(/^range_/,'')]=v;}else{let r=rules.find(r=>r.good_id===p.good_id);if(!r){r={good_id:p.good_id,version:0};rules.push(r);}if(r.version!==p.version)return{error:'Weapon rules changed.'};Object.assign(r,p,{version:r.version+1});}return{message:'Range controls saved and audited.',state:read()};};
 const setup=p=>{if(p.config)Object.assign(config,p.config);if(p.expire&&current())current().ends_at=new Date(Date.now()-2000).toISOString();};
 return {read,action,manage,setup};
}
